WITH ranked AS (SELECT OriginCode, round(100 - avg(DepDel15) * 100, 2) AS otp_rate, count() AS total_departures FROM ontime.fact_ontime WHERE Cancelled = 0 AND DepDelay IS NOT NULL GROUP BY OriginCode HAVING total_departures >= 100000) SELECT min(otp_rate) AS worst_otp, round(median(otp_rate), 2) AS median_otp, round(median(otp_rate) - min(otp_rate), 2) AS spread_pp, count() AS qualifying_airports FROM ranked
